sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || !newValue) {
        return;
    }

    var ga = new GlideAjax("TrainingValidationUtils"); 
    var scheduleDate = g_form.getValue("schedule_date"); 
    var courseId = g_form.getValue("course");  

    var formattedDate = formatDateForQuery(scheduleDate);

    var encodedQuery = buildEncodedQuery(formattedDate, courseId);

    ga.addParam("sysparm_encodedQuery", encodedQuery);
    ga.addParam("sysparm_name", "checkCourseSchedule");

    ga.getXML(function (response) {
        var responseAnswer = response.responseXML.documentElement.getAttribute("answer");
        var scheduleList = JSON.parse(responseAnswer);  

        if (scheduleList.length > 0) {
            g_form.addErrorMessage("Este curso já está agendado para essa data, selecione outra.");
            g_form.setValue("schedule_date", ""); 
        } else {
            g_form.clearMessages(); 
        }
    });
}

function formatDateForQuery(dateString) {
    var parts = dateString.split("/");  
    return parts[2] + "-" + parts[1] + "-" + parts[0];  
}

function buildEncodedQuery(formattedDate, courseId) {
    return "course.sys_id=" + courseId + "^schedule_dateON" + formattedDate + "@javascript:gs.dateGenerate('" + formattedDate + "', 'start')" + "@javascript:gs.dateGenerate('" + formattedDate + "', 'end')";
}
